@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');
.ui-root { --ui-primary: #3E7B4A; --ui-primary-text: #ffffff; --ui-bg: #FBF6EC; --ui-surface: #FFFDF8; --ui-surface-2: color-mix(in srgb, #2B2A24 6%, #FFFDF8); --ui-text: #2B2A24; --ui-muted: #7A7467; --ui-border: color-mix(in srgb, #2B2A24 14%, #FBF6EC); --ui-success: #2E7D4F; --ui-warning: #d97706; --ui-danger: #B3412E; --ui-info: #2563eb; --ui-radius: 16px; --ui-radius-sm: calc(16px / 2); --ui-space: 4px; --ui-shadow: 0 1px 2px rgb(16 24 40 / 0.06), 0 4px 12px rgb(16 24 40 / 0.06); --ui-font: 'Inter', system-ui, sans-serif; --ui-font-heading: 'Inter', system-ui, sans-serif; font-family: var(--ui-font); font-size: 15px; line-height: 1.5; color: var(--ui-text); background: var(--ui-bg); }
.ui-root h1, .ui-root h2, .ui-root h3 { font-family: var(--ui-font-heading); }

/* Stats */
.ui-root .ui-stat { display: flex; flex-direction: column; gap: calc(var(--ui-space) * 2); padding: calc(var(--ui-space) * 6); background: var(--ui-surface); color: var(--ui-text); border: 1px solid var(--ui-border); border-radius: var(--ui-radius); box-shadow: var(--ui-shadow); min-width: 0; }
.ui-root .ui-stat-label { display: block; font-family: var(--ui-font); font-size: 14px; font-weight: 500; line-height: 1.4; color: var(--ui-muted); }
.ui-root .ui-stat-value { display: block; font-family: var(--ui-font-heading); font-size: 32px; font-weight: 700; line-height: 1.15; letter-spacing: -0.01em; color: var(--ui-text); font-variant-numeric: tabular-nums; overflow-wrap: anywhere; }
.ui-root .ui-stat-note { display: inline-flex; align-self: flex-start; align-items: center; gap: var(--ui-space); padding: calc(var(--ui-space) / 2) calc(var(--ui-space) * 2); font-family: var(--ui-font); font-size: 14px; font-weight: 600; line-height: 1.4; color: var(--ui-success); background: var(--ui-surface-2); border-radius: var(--ui-radius-sm); }
.ui-root .ui-stat:hover { border-color: color-mix(in srgb, var(--ui-primary) 30%, var(--ui-border)); transition: border-color 150ms ease; }
@media (max-width: 899px) {
  .ui-root .ui-stat { padding: calc(var(--ui-space) * 5); }
  .ui-root .ui-stat-value { font-size: 28px; }
}

/* Sections and layout */
.ui-root .ui-section { display: flex; flex-direction: column; gap: calc(var(--ui-space) * 6); padding-block: calc(var(--ui-space) * 12); font-family: var(--ui-font); color: var(--ui-text); }
.ui-root .ui-section + .ui-section { border-top: 1px solid var(--ui-border); }
.ui-root .ui-section-title { margin: 0; font-family: var(--ui-font-heading); font-size: 24px; font-weight: 600; line-height: 1.25; letter-spacing: -0.01em; color: var(--ui-text); display: flex; align-items: center; gap: calc(var(--ui-space) * 3); }
.ui-root .ui-section-title::before { content: ""; flex: 0 0 auto; width: calc(var(--ui-space) * 2); height: calc(var(--ui-space) * 6); border-radius: 999px; background: var(--ui-primary); }
.ui-root .ui-grid { display: grid; gap: calc(var(--ui-space) * 4); grid-template-columns: 1fr; align-items: stretch; }
.ui-root .ui-grid-2 { display: grid; gap: calc(var(--ui-space) * 4); grid-template-columns: repeat(2, minmax(0, 1fr)); align-items: stretch; }
.ui-root .ui-grid-3 { display: grid; gap: calc(var(--ui-space) * 4); grid-template-columns: repeat(3, minmax(0, 1fr)); align-items: stretch; }
.ui-root .ui-grid-4 { display: grid; gap: calc(var(--ui-space) * 4); grid-template-columns: repeat(4, minmax(0, 1fr)); align-items: stretch; }
.ui-root .ui-row { display: flex; flex-direction: row; flex-wrap: wrap; align-items: center; gap: calc(var(--ui-space) * 4); }
.ui-root .ui-stack { display: flex; flex-direction: column; align-items: stretch; gap: calc(var(--ui-space) * 4); }
@media (max-width: 899px) {
  .ui-root .ui-grid-2 { grid-template-columns: 1fr; }
  .ui-root .ui-grid-3, .ui-root .ui-grid-4 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .ui-root .ui-section { padding-block: calc(var(--ui-space) * 9); }
}
@media (max-width: 599px) {
  .ui-root .ui-grid-3, .ui-root .ui-grid-4 { grid-template-columns: 1fr; }
  .ui-root .ui-section-title { font-size: 20px; }
}

/* Lists */
.ui-root .ui-list { list-style: none; margin: 0; padding: 0; background: var(--ui-surface); border: 1px solid var(--ui-border); border-radius: var(--ui-radius); box-shadow: var(--ui-shadow); overflow: hidden; font-family: var(--ui-font); }
.ui-root .ui-list-item { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 16px 24px; border-top: 1px solid var(--ui-border); color: var(--ui-text); transition: background-color 150ms ease, box-shadow 150ms ease; }
.ui-root .ui-list-item:first-child { border-top: 0; }
.ui-root .ui-list-item:hover { background: var(--ui-surface-2); }
.ui-root .ui-list-item:focus-visible { outline: 2px solid var(--ui-primary); outline-offset: -2px; }
.ui-root .ui-list-item.is-active { background: var(--ui-surface-2); box-shadow: inset 3px 0 0 var(--ui-primary); }
.ui-root .ui-list-item.is-disabled { color: var(--ui-muted); }
.ui-root .ui-list-item.is-disabled:hover { background: transparent; }
.ui-root .ui-list-main { display: flex; flex-direction: column; gap: 4px; flex: 1 1 auto; min-width: 0; font-size: 15px; line-height: 1.5; }
.ui-root .ui-list-main strong { font-weight: 600; color: var(--ui-text); }
.ui-root .ui-list-item.is-disabled .ui-list-main strong { color: var(--ui-muted); }
.ui-root .ui-list-side { display: flex; align-items: center; gap: 8px; flex: 0 0 auto; }
@media (max-width: 899px) {
  .ui-root .ui-list-item { flex-wrap: wrap; padding: 12px 16px; }
  .ui-root .ui-list-side { margin-left: auto; }
}

/* Buttons and links */
.ui-root .ui-btn { display: inline-flex; align-items: center; justify-content: center; gap: calc(var(--ui-space) * 2); min-height: 44px; padding: calc(var(--ui-space) * 3) calc(var(--ui-space) * 5); border: 1px solid transparent; border-radius: var(--ui-radius-sm); font-family: var(--ui-font); font-size: 15px; font-weight: 600; line-height: 1.2; text-decoration: none; white-space: nowrap; cursor: pointer; transition: background-color 150ms ease, border-color 150ms ease, color 150ms ease; }
.ui-root a.ui-btn { text-decoration: none; }
.ui-root .ui-btn:focus-visible { outline: 2px solid var(--ui-primary); outline-offset: 2px; }
.ui-root .ui-btn-primary { background: var(--ui-primary); border-color: var(--ui-primary); color: var(--ui-primary-text); }
.ui-root .ui-btn-primary:hover, .ui-root .ui-btn-primary.is-active { background: var(--ui-success); border-color: var(--ui-success); color: var(--ui-primary-text); }
.ui-root .ui-btn-secondary { background: var(--ui-surface); border-color: var(--ui-border); color: var(--ui-text); }
.ui-root .ui-btn-secondary:hover, .ui-root .ui-btn-secondary.is-active { border-color: var(--ui-primary); color: var(--ui-primary); background: var(--ui-surface-2); }
.ui-root .ui-btn-ghost { background: transparent; border-color: transparent; color: var(--ui-primary); }
.ui-root .ui-btn-ghost:hover, .ui-root .ui-btn-ghost.is-active { background: var(--ui-surface-2); color: var(--ui-primary); }
.ui-root .ui-btn-danger { background: var(--ui-danger); border-color: var(--ui-danger); color: var(--ui-primary-text); }
.ui-root .ui-btn-danger:hover, .ui-root .ui-btn-danger.is-active { background: var(--ui-surface); border-color: var(--ui-danger); color: var(--ui-danger); }
.ui-root .ui-btn-sm { min-height: 32px; padding: calc(var(--ui-space) * 2) calc(var(--ui-space) * 3); font-size: 14px; gap: var(--ui-space); }
.ui-root .ui-btn.is-disabled, .ui-root .ui-btn:disabled { opacity: 0.5; cursor: not-allowed; pointer-events: none; }
.ui-root .ui-link { color: var(--ui-primary); font-family: var(--ui-font); font-size: 15px; font-weight: 600; text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 3px; transition: color 150ms ease; }
.ui-root a.ui-link:hover { color: var(--ui-text); }
.ui-root .ui-link:focus-visible { outline: 2px solid var(--ui-primary); outline-offset: 2px; border-radius: var(--ui-space); }
.ui-root .ui-link.is-disabled { color: var(--ui-muted); pointer-events: none; text-decoration: none; }

/* Badges and people */
.ui-root .ui-badge { display: inline-flex; align-items: center; gap: 6px; padding: 2px 10px; border-radius: 999px; border: 1px solid var(--ui-border); background: var(--ui-surface-2); color: var(--ui-text); font-family: var(--ui-font); font-size: 14px; font-weight: 600; line-height: 20px; white-space: nowrap; vertical-align: middle; }
.ui-root .ui-badge::before { content: ""; width: 6px; height: 6px; border-radius: 999px; background: currentColor; flex: 0 0 auto; }
.ui-root .ui-badge-success { color: var(--ui-success); border-color: color-mix(in srgb, var(--ui-success) 30%, var(--ui-surface)); background: color-mix(in srgb, var(--ui-success) 10%, var(--ui-surface)); }
.ui-root .ui-badge-warning { color: var(--ui-text); border-color: color-mix(in srgb, var(--ui-warning) 45%, var(--ui-surface)); background: color-mix(in srgb, var(--ui-warning) 18%, var(--ui-surface)); }
.ui-root .ui-badge-warning::before { background: var(--ui-warning); }
.ui-root .ui-badge-danger { color: var(--ui-danger); border-color: color-mix(in srgb, var(--ui-danger) 30%, var(--ui-surface)); background: color-mix(in srgb, var(--ui-danger) 10%, var(--ui-surface)); }
.ui-root .ui-badge-info { color: var(--ui-info); border-color: color-mix(in srgb, var(--ui-info) 28%, var(--ui-surface)); background: color-mix(in srgb, var(--ui-info) 9%, var(--ui-surface)); }
.ui-root .ui-badge-neutral { color: var(--ui-text); border-color: var(--ui-border); background: var(--ui-surface-2); }
.ui-root .ui-avatar { display: inline-flex; align-items: center; justify-content: center; width: 40px; height: 40px; border-radius: 999px; background: var(--ui-primary); color: var(--ui-primary-text); font-family: var(--ui-font-heading); font-size: 14px; font-weight: 600; line-height: 1; letter-spacing: 0.02em; text-transform: uppercase; flex: 0 0 auto; box-shadow: 0 0 0 2px var(--ui-surface); user-select: none; }

/* Tables */
.ui-root .ui-table-wrap { box-sizing: border-box; width: 100%; overflow-x: auto; background: var(--ui-surface); border: 1px solid var(--ui-border); border-radius: var(--ui-radius); box-shadow: var(--ui-shadow); margin-block: calc(var(--ui-space) * 6); }
.ui-root .ui-table { width: 100%; min-width: 480px; border-collapse: separate; border-spacing: 0; font-family: var(--ui-font); font-size: 15px; line-height: 1.5; color: var(--ui-text); text-align: left; }
.ui-root .ui-table th { padding: calc(var(--ui-space) * 4) calc(var(--ui-space) * 6); background: var(--ui-surface-2); border-bottom: 1px solid var(--ui-border); font-family: var(--ui-font-heading); font-size: 14px; font-weight: 600; line-height: 1.4; color: var(--ui-text); white-space: nowrap; vertical-align: middle; }
.ui-root .ui-table td { padding: calc(var(--ui-space) * 4) calc(var(--ui-space) * 6); border-bottom: 1px solid var(--ui-border); color: var(--ui-text); vertical-align: middle; transition: background-color 150ms ease; }
.ui-root .ui-table th:last-child, .ui-root .ui-table td:last-child { text-align: right; }
.ui-root .ui-table tbody tr:last-child td { border-bottom: none; }
.ui-root .ui-table tbody tr:hover td { background: color-mix(in srgb, var(--ui-primary) 5%, var(--ui-surface)); }
.ui-root .ui-table tbody tr.is-active td { background: color-mix(in srgb, var(--ui-primary) 9%, var(--ui-surface)); }
.ui-root .ui-table tbody tr.is-disabled td { color: var(--ui-muted); background: var(--ui-surface); }

/* Page header */
.ui-root .ui-page { box-sizing: border-box; max-width: 1200px; margin: 0 auto; padding: calc(var(--ui-space) * 12) calc(var(--ui-space) * 8); display: flex; flex-direction: column; gap: calc(var(--ui-space) * 12); color: var(--ui-text); font-family: var(--ui-font); font-size: 15px; line-height: 1.5; }
.ui-root .ui-page-header { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: calc(var(--ui-space) * 4); padding-bottom: calc(var(--ui-space) * 6); border-bottom: 1px solid var(--ui-border); }
.ui-root .ui-page-header > div:first-child { min-width: 0; }
.ui-root .ui-page-header h1 { margin: 0; font-family: var(--ui-font-heading); font-size: 30px; font-weight: 700; line-height: 1.2; letter-spacing: -0.01em; color: var(--ui-text); }
.ui-root .ui-page-header .ui-meta { margin: calc(var(--ui-space) * 1.5) 0 0; }
.ui-root .ui-meta { margin: 0; font-size: 14px; font-weight: 500; line-height: 1.5; color: color-mix(in srgb, var(--ui-text) 78%, var(--ui-bg)); }
.ui-root .ui-actions { display: flex; flex-wrap: wrap; align-items: center; gap: calc(var(--ui-space) * 3); }
.ui-root .ui-page-header .ui-actions { flex-shrink: 0; }
@media (max-width: 900px) {
  .ui-root .ui-page { padding: calc(var(--ui-space) * 8) calc(var(--ui-space) * 4); gap: calc(var(--ui-space) * 8); }
  .ui-root .ui-page-header { align-items: flex-start; }
  .ui-root .ui-page-header h1 { font-size: 26px; }
  .ui-root .ui-page-header .ui-actions { width: 100%; }
}

/* Cards */
.ui-root .ui-card { display: flex; flex-direction: column; min-width: 0; background: var(--ui-surface); color: var(--ui-text); border: 1px solid var(--ui-border); border-radius: var(--ui-radius); box-shadow: var(--ui-shadow); overflow: hidden; font-family: var(--ui-font); }
.ui-root .ui-card-header { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: calc(var(--ui-space) * 3); padding: calc(var(--ui-space) * 5) calc(var(--ui-space) * 6); border-bottom: 1px solid var(--ui-border); }
.ui-root .ui-card-header h3 { margin: 0; font-family: var(--ui-font-heading); font-size: 18px; font-weight: 600; line-height: 1.3; color: var(--ui-text); }
.ui-root .ui-card-body { flex: 1 1 auto; padding: calc(var(--ui-space) * 6); font-size: 15px; line-height: 1.5; color: var(--ui-text); }
.ui-root .ui-card-body p { margin: 0; }
.ui-root .ui-card-body p + p { margin-top: calc(var(--ui-space) * 3); }
.ui-root .ui-card-footer { display: flex; flex-wrap: wrap; align-items: center; gap: calc(var(--ui-space) * 3); padding: calc(var(--ui-space) * 4) calc(var(--ui-space) * 6); background: var(--ui-surface-2); border-top: 1px solid var(--ui-border); }
.ui-root a.ui-card-link { display: flex; flex-direction: column; text-decoration: none; color: inherit; cursor: pointer; transition: transform 0.15s ease, box-shadow 0.15s ease, border-color 0.15s ease; }
.ui-root a.ui-card-link:hover { transform: translateY(-2px); border-color: color-mix(in srgb, var(--ui-primary) 40%, var(--ui-border)); box-shadow: 0 8px 24px color-mix(in srgb, var(--ui-text) 12%, transparent); }
.ui-root a.ui-card-link:hover .ui-card-header h3 { color: var(--ui-primary); }
.ui-root a.ui-card-link:focus-visible { outline: 2px solid var(--ui-primary); outline-offset: 3px; }
.ui-root a.ui-card-link .ui-card-header h3 { transition: color 0.15s ease; }

/* Progress */
.ui-root .ui-progress { display: block; box-sizing: border-box; width: 100%; height: 8px; margin: calc(var(--ui-space) * 3) 0; padding: 0; overflow: hidden; border: 1px solid var(--ui-border); border-radius: 999px; background: var(--ui-surface-2); box-shadow: inset 0 1px 2px rgb(16 24 40 / 0.06); }
.ui-root .ui-progress > span { display: block; box-sizing: border-box; max-width: 100%; height: 100%; border-radius: 999px; background: var(--ui-primary); transition: width 200ms ease; }

/* Details */
.ui-root .ui-kv { display: grid; grid-template-columns: minmax(120px, max-content) 1fr; column-gap: calc(var(--ui-space) * 6); row-gap: 0; margin: 0; padding: calc(var(--ui-space) * 4); background: var(--ui-surface); color: var(--ui-text); border: 1px solid var(--ui-border); border-radius: var(--ui-radius-sm); box-shadow: var(--ui-shadow); font-family: var(--ui-font); font-size: 15px; line-height: 1.5; }
.ui-root .ui-kv dt { margin: 0; padding: calc(var(--ui-space) * 3) 0; border-bottom: 1px solid var(--ui-border); font-size: 14px; font-weight: 500; color: var(--ui-text); }
.ui-root .ui-kv dd { margin: 0; padding: calc(var(--ui-space) * 3) 0; border-bottom: 1px solid var(--ui-border); font-size: 15px; font-weight: 600; color: var(--ui-text); overflow-wrap: anywhere; }
.ui-root .ui-kv > :nth-last-child(-n + 2) { border-bottom: 0; }
@media (max-width: 900px) {
  .ui-root .ui-kv { grid-template-columns: 1fr; row-gap: 0; }
  .ui-root .ui-kv dt { padding-bottom: 0; border-bottom: 0; color: var(--ui-muted); }
  .ui-root .ui-kv dd { padding-top: calc(var(--ui-space) * 1); }
}

/* Timeline */
.ui-root .ui-timeline { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: calc(var(--ui-space) * 4); font-family: var(--ui-font); }
.ui-root .ui-timeline-item { position: relative; margin: 0; padding-left: calc(var(--ui-space) * 8); font-size: 15px; line-height: 1.5; color: var(--ui-text); }
.ui-root .ui-timeline-item::before { content: ''; position: absolute; left: 0; top: 4px; width: 12px; height: 12px; border-radius: 999px; background: var(--ui-border); box-shadow: 0 0 0 4px var(--ui-surface); transition: background-color 150ms ease, box-shadow 150ms ease; }
.ui-root .ui-timeline-item::after { content: ''; position: absolute; left: 5px; top: 20px; bottom: calc(var(--ui-space) * -4); width: 2px; border-radius: 999px; background: var(--ui-border); }
.ui-root .ui-timeline-item:last-child::after { display: none; }
.ui-root .ui-timeline-item p { margin: 0; font-weight: 500; color: var(--ui-text); }
.ui-root .ui-timeline-time { display: block; margin-bottom: calc(var(--ui-space) * 1); font-size: 14px; font-weight: 500; line-height: 1.4; color: var(--ui-muted); }
.ui-root .ui-timeline-item.is-active::before { background: var(--ui-primary); box-shadow: 0 0 0 4px var(--ui-surface),
              0 0 0 7px color-mix(in srgb, var(--ui-primary) 18%, var(--ui-surface)); }
.ui-root .ui-timeline-item.is-active .ui-timeline-time { color: var(--ui-primary); }
.ui-root .ui-timeline-item.is-active p { font-weight: 600; }

/* Messages and empty states */
.ui-root .ui-empty { display: flex; flex-direction: column; align-items: center; text-align: center; gap: calc(var(--ui-space) * 3); padding: calc(var(--ui-space) * 8) calc(var(--ui-space) * 6); background: var(--ui-surface); border: 1px solid var(--ui-border); border-radius: var(--ui-radius); box-shadow: var(--ui-shadow); font-family: var(--ui-font); color: var(--ui-text); }
.ui-root .ui-empty-title { margin: 0; font-family: var(--ui-font-heading); font-size: 18px; font-weight: 600; line-height: 1.3; color: var(--ui-text); }
.ui-root .ui-empty-text { margin: 0; max-width: 42ch; font-size: 15px; line-height: 1.5; color: var(--ui-muted); }
.ui-root .ui-alert { position: relative; display: flex; align-items: flex-start; gap: calc(var(--ui-space) * 3); padding: calc(var(--ui-space) * 3) calc(var(--ui-space) * 4); font-family: var(--ui-font); font-size: 15px; font-weight: 500; line-height: 1.5; color: var(--ui-text); background: var(--ui-surface); border: 1px solid var(--ui-border); border-left: 4px solid var(--ui-muted); border-radius: var(--ui-radius-sm); box-shadow: var(--ui-shadow); }
.ui-root .ui-alert::before { content: ""; flex: 0 0 auto; width: 8px; height: 8px; margin-top: 7px; border-radius: 999px; background: currentColor; }
.ui-root .ui-alert-info { color: var(--ui-text); background: color-mix(in srgb, var(--ui-info) 10%, var(--ui-surface)); border-left-color: var(--ui-info); }
.ui-root .ui-alert-info::before { color: var(--ui-info); }
.ui-root .ui-alert-success { color: var(--ui-text); background: color-mix(in srgb, var(--ui-success) 12%, var(--ui-surface)); border-left-color: var(--ui-success); }
.ui-root .ui-alert-success::before { color: var(--ui-success); }
.ui-root .ui-alert-warning { color: var(--ui-text); background: color-mix(in srgb, var(--ui-warning) 14%, var(--ui-surface)); border-left-color: var(--ui-warning); }
.ui-root .ui-alert-warning::before { color: var(--ui-warning); }
.ui-root .ui-alert-danger { color: var(--ui-text); background: color-mix(in srgb, var(--ui-danger) 12%, var(--ui-surface)); border-left-color: var(--ui-danger); }
.ui-root .ui-alert-danger::before { color: var(--ui-danger); }

/* Forms */
.ui-root .ui-form { display: flex; flex-direction: column; gap: calc(var(--ui-space) * 4); padding: calc(var(--ui-space) * 6); background: var(--ui-surface); color: var(--ui-text); border: 1px solid var(--ui-border); border-radius: var(--ui-radius); box-shadow: var(--ui-shadow); font-family: var(--ui-font); }
.ui-root .ui-field { display: flex; flex-direction: column; gap: calc(var(--ui-space) * 2); font-size: 15px; font-weight: 500; color: var(--ui-text); }
.ui-root .ui-field > span:first-child { font-size: 14px; font-weight: 600; color: var(--ui-text); }
.ui-root .ui-input, .ui-root .ui-select, .ui-root .ui-textarea { box-sizing: border-box; width: 100%; min-height: 44px; padding: calc(var(--ui-space) * 2) calc(var(--ui-space) * 3); font-family: var(--ui-font); font-size: 15px; line-height: 1.5; font-weight: 400; color: var(--ui-text); background: var(--ui-surface); border: 1px solid var(--ui-border); border-radius: var(--ui-radius-sm); transition: border-color 150ms ease, box-shadow 150ms ease; }
.ui-root .ui-textarea { min-height: calc(var(--ui-space) * 24); resize: vertical; }
.ui-root .ui-input::placeholder, .ui-root .ui-textarea::placeholder { color: color-mix(in srgb, var(--ui-muted) 85%, var(--ui-text)); }
.ui-root .ui-input:hover:not(:disabled), .ui-root .ui-select:hover:not(:disabled), .ui-root .ui-textarea:hover:not(:disabled) { border-color: color-mix(in srgb, var(--ui-primary) 45%, var(--ui-border)); }
.ui-root .ui-input:focus, .ui-root .ui-select:focus, .ui-root .ui-textarea:focus { outline: none; border-color: var(--ui-primary); box-shadow: 0 0 0 3px color-mix(in srgb, var(--ui-primary) 22%, transparent); }
.ui-root .ui-input:disabled, .ui-root .ui-select:disabled, .ui-root .ui-textarea:disabled { background: var(--ui-surface-2); color: color-mix(in srgb, var(--ui-muted) 85%, var(--ui-text)); cursor: not-allowed; }
