.ui-root .ui-error { display: inline-flex; align-items: center; align-self: flex-start; gap: calc(var(--ui-space) * 2); padding: calc(var(--ui-space) / 1) calc(var(--ui-space) * 3); font-size: 14px; font-weight: 600; line-height: 1.4; color: var(--ui-danger); background: color-mix(in srgb, var(--ui-danger) 10%, var(--ui-surface)); border-radius: 999px; }

/* Pictures, maps and charts */
.ui-root .ui-media { position: relative; display: flex; align-items: center; justify-content: center; min-height: 200px; padding: calc(var(--ui-space) * 4); overflow: hidden; background: var(--ui-surface-2); color: var(--ui-text); font-family: var(--ui-font); font-size: 14px; line-height: 1.5; border: 1px solid var(--ui-border); border-radius: var(--ui-radius); box-shadow: var(--ui-shadow); }
