.ui-root .ui-map { position: relative; width: 100%; min-height: 320px; overflow: hidden; background-color: var(--ui-surface-2); background-image:
    repeating-linear-gradient(0deg, transparent 0 39px, color-mix(in srgb, var(--ui-border) 70%, transparent) 39px 40px),
    repeating-linear-gradient(90deg, transparent 0 39px, color-mix(in srgb, var(--ui-border) 70%, transparent) 39px 40px); border: 1px solid var(--ui-border); border-radius: var(--ui-radius); box-shadow: var(--ui-shadow); }
