}

/* Tabs and filters */
.ui-root .ui-breadcrumb { display: flex; flex-wrap: wrap; align-items: center; gap: calc(var(--ui-space) * 2); font-size: 14px; line-height: 1.4; color: var(--ui-text); margin-bottom: calc(var(--ui-space) * 4); }
