.ui-root .ui-breadcrumb a:hover { text-decoration: underline; }
.ui-root .ui-breadcrumb a::after { content: "/"; margin-left: calc(var(--ui-space) * 2); color: var(--ui-text); }
.ui-root .ui-breadcrumb span { font-weight: 600; color: var(--ui-text); }
.ui-root .ui-breadcrumb a:focus-visible { outline: 2px solid var(--ui-primary); outline-offset: 2px; border-radius: var(--ui-radius-sm); }
.ui-root .ui-tabs { display: inline-flex; flex-wrap: wrap; max-width: 100%; gap: var(--ui-space); padding: var(--ui-space); background: var(--ui-surface-2); border: 1px solid var(--ui-border); border-radius: 999px; }
