.ui-root .ui-filter-bar { display: flex; flex-wrap: wrap; align-items: center; gap: calc(var(--ui-space) * 3); padding: calc(var(--ui-space) * 4); background: var(--ui-surface); border: 1px solid var(--ui-border); border-radius: var(--ui-radius); box-shadow: var(--ui-shadow); }
.ui-root .ui-search { flex: 1 1 260px; min-width: 0; height: 40px; padding: 0 calc(var(--ui-space) * 3); border: 1px solid var(--ui-border); border-radius: 999px; background: var(--ui-surface); color: var(--ui-text); font-family: var(--ui-font); font-size: 14px; transition: border-color 0.15s ease, box-shadow 0.15s ease; }
