.ui-root .ui-search:hover { border-color: var(--ui-primary); }
.ui-root .ui-search:focus { outline: 2px solid var(--ui-primary); outline-offset: 2px; border-color: var(--ui-primary); }
.ui-root .ui-pagination { display: flex; flex-wrap: wrap; align-items: center; justify-content: center; gap: calc(var(--ui-space) * 4); margin-top: calc(var(--ui-space) * 6); font-size: 14px; color: var(--ui-text); }
.ui-root .ui-pagination a { padding: calc(var(--ui-space) * 2) calc(var(--ui-space) * 4); border: 1px solid var(--ui-border); border-radius: 999px; background: var(--ui-surface); color: var(--ui-primary); font-weight: 500; text-decoration: none; transition: border-color 0.15s ease, background-color 0.15s ease; }
.ui-root .ui-pagination a:hover { border-color: var(--ui-primary); background: var(--ui-surface-2); }
.ui-root .ui-pagination a:focus-visible { outline: 2px solid var(--ui-primary); outline-offset: 2px; }
.ui-root .ui-pagination span { padding: 0 calc(var(--ui-space) * 2); font-weight: 500; color: var(--ui-text); }

/* Top bar and menu */
.ui-shell { position: relative; min-height: 100vh; background: var(--ui-bg); color: var(--ui-text); font-family: var(--ui-font); }
.ui-sidebar { position: sticky; top: 0; z-index: 5; display: flex; align-items: center; gap: 24px; height: 68px; box-sizing: border-box; padding: 0 232px 0 24px; background: var(--ui-surface); border-bottom: 1px solid var(--ui-border); }
