.ui-user { display: flex; align-items: center; gap: 6px; font-size: 14px; line-height: 1.4; color: var(--ui-text); white-space: nowrap; pointer-events: auto; }
.ui-content { box-sizing: border-box; max-width: 1120px; margin: 0 auto; padding: 32px 24px 64px; }
